function status = PlotBetaEvolution(beta_all,grlist)
%  Program for plotting the evolution of the modal weights 
%
%    Input:   (1) file with the weights generated by
%                       ExpansionCoefficientsMultiFrames script
%             (2) array with a list of the grains begin plotted
%
%     Output: (1) plots of the harmonic weights versus the load step
%
%    Currently set up to plot data for 10 modes only.  Need to expand
%    linetype and the legend to handle more modes if desired.
  
    i=10;
    
     [dum,ngrns] = size(grlist);
  
    for iplt =1:1:ngrns
        
    grainnum = grlist(iplt);
    
        
   betafile = beta_all(:,:,grainnum);     
    
   [m,n] = size(betafile);
   nframes = m;
   nmodes = n;
   
  for imode=2:1:nmodes
        betafile(:,imode) = betafile(:,imode)./betafile(:,1);
  end
        
  maxbeta = 0.;
  minbeta = 0.;

  for ifr=1:1:nframes
      for jmn = 2:1:nmodes
            if(betafile(ifr,jmn)>maxbeta) 
                maxbeta=betafile(ifr,jmn);
            end
            if(betafile(ifr,jmn)<minbeta) 
                minbeta=betafile(ifr,jmn); 
            end  
      end
  end 

   
   ab_label = 'Load Step';
   ord_label = 'Mode Weight (beta)';
   plot_title = ['Mode Weight Evolution ' num2str(grainnum)];

   
   framenum = zeros(nframes,1);
   betavals = zeros(nframes,1);
   for ifr = 1:1:nframes
       framenum(ifr) = ifr;
   end
   maxframenum = max(framenum);
   

   linetype =[ '-b' '--r' '--g' '--b' ':r' ':g' ':b' '--r' '--g' '--b' ];
   
    i=i+1;
    
    figure(i)
    
    
    clf;    

    hold 'on';
  
    for imode = 2:1:nmodes
        
        betavals(:) = betafile(:,imode);
        
        p = plot(framenum,betavals,linetype(imode));

        set(gca,'Box','on','LineWidth',2,'FontName','Helvetica','FontSize',14);
        set(p,'LineWidth',2)
    end

    
axis([0 max(framenum) 1.5*minbeta 1.5*maxbeta]);
xlabel(ab_label); 
ylabel(ord_label);   
title(plot_title); 
legend('mode 2', 'mode 3', 'mode 4', 'mode 5', 'mode 6', 'mode 7', 'mode 8', 'mode 9', 'mode 10' );
        
    hold 'off'
    
    status = 'done with plot';
    
    
    
end
    end

